      backup_text =
        "# EMOJIPAINT MVU #\n\n\
         type Emoji = String in\n\
         type Canvas = [[Emoji]] in\n\
         type Row = Int in\n\
         type Col = Int in\n\n\
         type Model = (\n\
         canvas = Canvas,    # The 2D grid of emojis #\n\
         brush = Emoji,      # The currently selected emoji #\n\
         palette = [Emoji]   # The list of available emojis #\n\
         ) in\n\n\
         type Action =\n\
         + SetBrush(Int)         # Set the brush using a palette index #\n\
         + PaintCell(Row, Col)   # Stamp the current emoji at the specified \
         position #\n\
         + ClearCell(Row, Col)   # Clear the emoji at the specified position #\n\
         + ClearGrid             # Clear the entire grid #\n\
         + PaintRow(Row)         # Fill the specified row with the current \
         emoji #\n\
         in\n\n\
         let init: Model = (\n\
         canvas = [\n\
         [\"\", \"\", \"\"],\n\
         [\"\", \"\", \"\"],\n\
         [\"\", \"\", \"\"]\n\
         ],\n\
         brush = \"\240\159\152\132\",\n\
         palette = [\"\240\159\152\132\", \"\240\159\152\133\", \
         \"\240\159\152\134\", \"\240\159\152\137\", \"\240\159\152\138\"]\n\
         ) in\n\n\
         let setCell: (Canvas, Row, Col, Emoji) -> Canvas =\n\
         fun canvas, row, col, emoji ->\n\
         mapi(canvas, fun (i, r) ->\n\
         if i == row\n\
         then mapi(r, fun (j, c) ->\n\
         if j == col\n\
         then emoji\n\
         else c)\n\
         else r)\n\
         in\n\n\
         let setRow: (Canvas, Row, Emoji) -> Canvas =\n\
         fun canvas, targetRow, emoji ->\n\
         mapi(canvas, fun (i, row) ->\n\
         if i == targetRow\n\
         then map(row, fun _ -> emoji)\n\
         else row)\n\
         in\n\n\
         let setAll: (Canvas, Emoji) -> Canvas =\n\
         fun (canvas, emoji) ->\n\
         map(canvas, fun row -> map(row, fun _ -> emoji))\n\
         in\n\n\
         let updateGrid: (Model, Canvas -> Canvas) -> Model =\n\
         fun (m, f) -> (f(m.canvas), m.brush, m.palette)\n\
         in\n\n\
         # Update the EmojiPaint app model based on an action #\n\
         let update: (Model, Action) -> Model =\n\
         fun m, action ->\n\
         case action\n\
         | SetBrush(idx) =>\n\
         (m.canvas, nth(m.palette, idx), m.palette)\n\
         | PaintCell(row, col) =>\n\
         updateGrid(m, fun c -> setCell(c, row, col, m.brush))\n\
         | ClearCell(row, col) =>\n\
         updateGrid(m, fun c -> setCell(c, row, col, \"\"))\n\
         | ClearGrid =>\n\
         updateGrid(m, fun c -> setAll(c, \"\"))\n\
         | PaintRow(row) =>\n\
         updateGrid(m, fun c -> setRow(c, row, m.brush))\n\
         end\n\
         in\n\n\
         let do: (Model, [Action]) -> Model =\n\
         fun (init: Model, actions: [Action]) ->\n\
         fold_left(actions, update, init)\n\
         in\n\n\
         # Tests #\n\n\
         test\n\
         let m = update(init, PaintCell(0, 0)) in\n\
         m.canvas == [[\"\240\159\152\132\", \"\", \"\"], [\"\", \"\", \"\"], \
         [\"\", \"\", \"\"]]\n\
         end;\n\n\
         test\n\
         let m = update(init, PaintRow(1)) in\n\
         m.canvas == [[\"\", \"\", \"\"], [\"\240\159\152\132\", \
         \"\240\159\152\132\", \"\240\159\152\132\"], [\"\", \"\", \"\"]]\n\
         end;\n\n\
         test\n\
         let m = do(init, [SetBrush(1), PaintCell(2, 2)]) in\n\
         m.canvas == [[\"\", \"\", \"\"], [\"\", \"\", \"\"], [\"\", \"\", \
         \"\240\159\152\133\"]]\n\
         && m.brush == \"\240\159\152\133\"\n\
         end;\n\n\
         test\n\
         let m = do(init, [PaintRow(0), ClearCell(0, 1)]) in\n\
         m.canvas == [[\"\240\159\152\132\", \"\", \"\240\159\152\132\"], \
         [\"\", \"\", \"\"], [\"\", \"\", \"\"]]\n\
         end;\n\n\
         test\n\
         let model = update(init, PaintCell(1, 1)) in\n\
         let (grid, _, _) = update(model, ClearGrid) in\n\
         grid == [[\"\", \"\", \"\"], [\"\", \"\", \"\"], [\"\", \"\", \"\"]]\n\
         end;\n\n\
         test\n\
         let m = do(init, [SetBrush(4), PaintCell(1, 2)]) in\n\
         m.canvas == [[\"\", \"\", \"\"], [\"\", \"\", \"\240\159\152\138\"], \
         [\"\", \"\", \"\"]]\n\
         end;\n\n\
         test\n\
         let m = do(init, [PaintRow(2), ClearCell(2, 0)]) in\n\
         m.canvas == [[\"\", \"\", \"\"], [\"\", \"\", \"\"], [\"\", \
         \"\240\159\152\132\", \"\240\159\152\132\"]]\n\
         end;\n\n\
         test\n\
         let m = do(init, [\n\
         PaintCell(0, 0),\n\
         PaintCell(1, 1),\n\
         PaintCell(2, 2),\n\
         ClearGrid\n\
         ]) in\n\
         m.canvas == [[\"\", \"\", \"\"], [\"\", \"\", \"\"], [\"\", \"\", \
         \"\"]]\n\
         end;\n\n\
         test\n\
         let m = do(init, [\n\
         PaintRow(0),\n\
         SetBrush(2),\n\
         PaintCell(1, 1)\n\
         ]) in\n\
         m.canvas == [[\"\240\159\152\132\", \"\240\159\152\132\", \
         \"\240\159\152\132\"], [\"\", \"\240\159\152\134\", \"\"], [\"\", \
         \"\", \"\"]]\n\
         end;\n\n\
         test\n\
         let m = do(init, [\n\
         PaintCell(0, 0),\n\
         PaintRow(2),\n\
         SetBrush(3),\n\
         PaintCell(1, 1),\n\
         ClearCell(2, 2)\n\
         ]) in\n\
         m.canvas == [[\"\240\159\152\132\", \"\", \"\"], [\"\", \
         \"\240\159\152\137\", \"\"], [\"\240\159\152\132\", \
         \"\240\159\152\132\", \"\"]]\n\
         && m.brush == \"\240\159\152\137\"\n\
         end;\n\n\
         do(init, [SetBrush(1), PaintCell(2, 2)])\n";
      refractors = "()";
    } )
